class RelayPriority(enum.Enum):
    
    NEVER = 0
    
    AUTO = 1
    
    ALWAYS = 2
    


class _UniffiFfiConverterTypeRelayPriority(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return RelayPriority.NEVER
        if variant == 2:
            return RelayPriority.AUTO
        if variant == 3:
            return RelayPriority.ALWAYS
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if value == RelayPriority.NEVER:
            return
        if value == RelayPriority.AUTO:
            return
        if value == RelayPriority.ALWAYS:
            return
        raise ValueError(value)

    @staticmethod
    def write(value, buf):
        if value == RelayPriority.NEVER:
            buf.write_i32(1)
        if value == RelayPriority.AUTO:
            buf.write_i32(2)
        if value == RelayPriority.ALWAYS:
            buf.write_i32(3)



